import json,os
p="/Users/kristinarash/SecondBrain/Inbox/meetings/.graphify_chunks/out/out_12.json"
d=json.load(open(p))
ids={n["id"] for n in d["nodes"]}
errs=[]
if len(ids)!=len(d["nodes"]): errs.append("dup node ids")
valid_rel={"references","conceptually_related_to","shares_data_with","semantically_similar_to","rationale_for","implements","cites"}
valid_conf={"EXTRACTED","INFERRED","AMBIGUOUS"}
files=set(os.listdir("/Users/kristinarash/SecondBrain/Inbox/meetings"))
for n in d["nodes"]:
    for k in ["id","label","file_type","source_file","source_location","source_url","captured_at","author","contributor"]:
        if k not in n: errs.append("node missing %s: %s"%(k,n.get("id")))
    if n["source_file"] not in files: errs.append("bad source_file "+n["source_file"])
for e in d["edges"]:
    if e["source"] not in ids: errs.append("missing src "+e["source"])
    if e["target"] not in ids: errs.append("missing tgt "+e["target"])
    if e["relation"] not in valid_rel: errs.append("bad rel "+e["relation"])
    if e["confidence"] not in valid_conf: errs.append("bad conf "+e["confidence"])
    s=e.get("confidence_score")
    if not isinstance(s,float): errs.append("bad score %r"%s)
    elif e["confidence"]=="EXTRACTED" and s!=1.0: errs.append("EXTRACTED not 1.0 %s->%s"%(e["source"],e["target"]))
    elif e["confidence"]=="INFERRED" and not (0.4<=s<=0.9): errs.append("INFERRED out of range %s"%s)
    elif e["confidence"]=="AMBIGUOUS" and not (0.1<=s<=0.3): errs.append("AMBIG out of range %s"%s)
    if e["source_file"] not in files: errs.append("bad edge source_file "+e["source_file"])
for h in d["hyperedges"]:
    for m in h["nodes"]:
        if m not in ids: errs.append("hyperedge missing "+m)
self_loops=[e for e in d["edges"] if e["source"]==e["target"]]
if self_loops: errs.append("self loops %d"%len(self_loops))
print("ERRORS:", len(errs))
for x in errs[:20]: print(" -",x)
from collections import Counter
print("relations:",Counter(e["relation"] for e in d["edges"]))
print("confidence:",Counter(e["confidence"] for e in d["edges"]))
print("files covered:",len({n["source_file"] for n in d["nodes"]}))
print("bytes:",os.path.getsize(p))
